using Contoso.Orders;

namespace Contoso.Orders.Tests;

[TestClass]
public sealed class OrderServiceTests
{
    private readonly OrderService _sut;

    public OrderServiceTests()
    {
        _sut = new OrderService();
    }

    private static List<OrderItem> CreateItems(params (string name, decimal price, int qty)[] items) =>
        items.Select(i => new OrderItem { ProductName = i.name, Price = i.price, Quantity = i.qty }).ToList();

    #region CreateOrder – Happy Path

    [TestMethod]
    public void CreateOrder_WithValidItems_ReturnsOrderWithCorrectCustomerId()
    {
        // Arrange
        var items = CreateItems(("Widget", 10m, 2));

        // Act
        var order = _sut.CreateOrder("cust-1", items);

        // Assert
        Assert.AreEqual("cust-1", order.CustomerId);
    }

    [TestMethod]
    public void CreateOrder_WithValidItems_AssignsNonEmptyId()
    {
        // Arrange
        var items = CreateItems(("Widget", 10m, 1));

        // Act
        var order = _sut.CreateOrder("cust-1", items);

        // Assert
        Assert.IsNotNull(order.Id);
        Assert.AreNotEqual(string.Empty, order.Id);
    }

    [TestMethod]
    public void CreateOrder_WithSingleItem_CalculatesCorrectTotal()
    {
        // Arrange
        var items = CreateItems(("Widget", 25.50m, 3));

        // Act
        var order = _sut.CreateOrder("cust-1", items);

        // Assert
        Assert.AreEqual(76.50m, order.Total);
    }

    [TestMethod]
    public void CreateOrder_WithMultipleItems_SumsTotalCorrectly()
    {
        // Arrange
        var items = CreateItems(("Widget", 10m, 2), ("Gadget", 5m, 4));

        // Act
        var order = _sut.CreateOrder("cust-1", items);

        // Assert
        Assert.AreEqual(40m, order.Total); // (10*2) + (5*4)
    }

    [TestMethod]
    public void CreateOrder_SetsCreatedAtToRecentUtcTime()
    {
        // Arrange
        var before = DateTime.UtcNow;
        var items = CreateItems(("Widget", 10m, 1));

        // Act
        var order = _sut.CreateOrder("cust-1", items);

        // Assert
        var after = DateTime.UtcNow;
        Assert.IsTrue(order.CreatedAt >= before && order.CreatedAt <= after,
            $"CreatedAt {order.CreatedAt} should be between {before} and {after}");
    }

    [TestMethod]
    public void CreateOrder_StoresItemsOnOrder()
    {
        // Arrange
        var items = CreateItems(("Widget", 10m, 1), ("Gadget", 5m, 2));

        // Act
        var order = _sut.CreateOrder("cust-1", items);

        // Assert
        Assert.HasCount(2, order.Items);
    }

    [TestMethod]
    public void CreateOrder_CalledTwice_AssignsUniqueIds()
    {
        // Arrange
        var items = CreateItems(("Widget", 10m, 1));

        // Act
        var order1 = _sut.CreateOrder("cust-1", items);
        var order2 = _sut.CreateOrder("cust-1", items);

        // Assert
        Assert.AreNotEqual(order1.Id, order2.Id);
    }

    #endregion

    #region CreateOrder – Validation

    [TestMethod]
    public void CreateOrder_NullCustomerId_ThrowsArgumentNullException()
    {
        // Arrange
        var items = CreateItems(("Widget", 10m, 1));

        // Act & Assert
        var ex = Assert.ThrowsExactly<ArgumentNullException>(
            () => _sut.CreateOrder(null!, items));
        Assert.AreEqual("customerId", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_NullItems_ThrowsArgumentNullException()
    {
        // Act & Assert
        var ex = Assert.ThrowsExactly<ArgumentNullException>(
            () => _sut.CreateOrder("cust-1", null!));
        Assert.AreEqual("items", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_EmptyItems_ThrowsInvalidOperationException()
    {
        // Act & Assert
        var ex = Assert.ThrowsExactly<InvalidOperationException>(
            () => _sut.CreateOrder("cust-1", []));
        Assert.Contains("no items", ex.Message, StringComparison.OrdinalIgnoreCase);
    }

    #endregion

    #region GetOrder

    [TestMethod]
    public void GetOrder_ExistingOrder_ReturnsMatchingOrder()
    {
        // Arrange
        var items = CreateItems(("Widget", 10m, 1));
        var created = _sut.CreateOrder("cust-1", items);

        // Act
        var retrieved = _sut.GetOrder(created.Id);

        // Assert
        Assert.IsNotNull(retrieved);
        Assert.AreSame(created, retrieved);
    }

    [TestMethod]
    public void GetOrder_NonExistentId_ReturnsNull()
    {
        // Act
        var result = _sut.GetOrder("does-not-exist");

        // Assert
        Assert.IsNull(result);
    }

    #endregion

    #region GetOrdersByCustomer

    [TestMethod]
    public void GetOrdersByCustomer_MultipleOrders_ReturnsAllForCustomer()
    {
        // Arrange
        var items = CreateItems(("Widget", 10m, 1));
        _sut.CreateOrder("cust-1", items);
        _sut.CreateOrder("cust-1", items);
        _sut.CreateOrder("cust-2", items);

        // Act
        var result = _sut.GetOrdersByCustomer("cust-1");

        // Assert
        Assert.HasCount(2, result);
    }

    [TestMethod]
    public void GetOrdersByCustomer_NoOrders_ReturnsEmptyList()
    {
        // Act
        var result = _sut.GetOrdersByCustomer("unknown");

        // Assert
        Assert.IsEmpty(result);
    }

    [TestMethod]
    public void GetOrdersByCustomer_ReturnsOnlyMatchingCustomerOrders()
    {
        // Arrange
        var items = CreateItems(("Widget", 10m, 1));
        _sut.CreateOrder("cust-1", items);
        _sut.CreateOrder("cust-2", items);

        // Act
        var result = _sut.GetOrdersByCustomer("cust-1");

        // Assert
        var single = Assert.ContainsSingle(result);
        Assert.AreEqual("cust-1", single.CustomerId);
    }

    #endregion
}

using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _sut;

    public PriceCalculatorTests()
    {
        _sut = new PriceCalculator();
    }

    #region CalculateTotal

    [TestMethod]
    [DataRow(10.00, 2, 0.10, 22.00, DisplayName = "10% tax")]
    [DataRow(10.00, 1, 0.00, 10.00, DisplayName = "No tax")]
    [DataRow(0.00, 5, 0.20, 0.00, DisplayName = "Zero price")]
    [DataRow(10.00, 0, 0.10, 0.00, DisplayName = "Zero quantity")]
    public void CalculateTotal_ValidInputs_ReturnsExpectedTotal(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        // Act
        var result = _sut.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        // Assert
        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    public void CalculateTotal_NegativeQuantity_ThrowsArgumentOutOfRangeException()
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _sut.CalculateTotal(10m, -1, 0.1m));
        Assert.AreEqual("quantity", ex.ParamName);
    }

    [TestMethod]
    public void CalculateTotal_NegativeUnitPrice_ThrowsArgumentOutOfRangeException()
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _sut.CalculateTotal(-5m, 1, 0.1m));
        Assert.AreEqual("unitPrice", ex.ParamName);
    }

    [TestMethod]
    [DataRow(-0.01, DisplayName = "Negative tax rate")]
    [DataRow(1.01, DisplayName = "Tax rate above 1")]
    public void CalculateTotal_InvalidTaxRate_ThrowsArgumentOutOfRangeException(double taxRate)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _sut.CalculateTotal(10m, 1, (decimal)taxRate));
        Assert.AreEqual("taxRate", ex.ParamName);
    }

    [TestMethod]
    public void CalculateTotal_BoundaryTaxRate_OneIsValid()
    {
        // Tax rate of exactly 1.0 (100%) is valid
        var result = _sut.CalculateTotal(10m, 1, 1.0m);

        Assert.AreEqual(20m, result);
    }

    #endregion

    #region ApplyDiscount

    [TestMethod]
    [DataRow(100.00, 10.0, 90.00, DisplayName = "10% discount")]
    [DataRow(200.00, 50.0, 100.00, DisplayName = "50% discount")]
    [DataRow(100.00, 0.0, 100.00, DisplayName = "No discount")]
    [DataRow(100.00, 100.0, 0.00, DisplayName = "100% discount")]
    public void ApplyDiscount_ValidInputs_ReturnsExpectedPrice(
        double price, double discount, double expected)
    {
        var result = _sut.ApplyDiscount((decimal)price, (decimal)discount);

        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(-1.0, DisplayName = "Negative discount")]
    [DataRow(100.01, DisplayName = "Discount above 100%")]
    public void ApplyDiscount_InvalidDiscount_ThrowsArgumentOutOfRangeException(double discount)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _sut.ApplyDiscount(100m, (decimal)discount));
    }

    #endregion

    #region FormatPrice

    [TestMethod]
    public void FormatPrice_DefaultCurrency_FormatsWithDollarSign()
    {
        var result = _sut.FormatPrice(42.5m);

        Assert.AreEqual("$42.50", result);
    }

    [TestMethod]
    public void FormatPrice_CustomCurrency_UsesProvidedSymbol()
    {
        var result = _sut.FormatPrice(42.5m, "€");

        Assert.StartsWith("€", result);
        Assert.AreEqual("€42.50", result);
    }

    [TestMethod]
    public void FormatPrice_RoundsToTwoDecimalPlaces()
    {
        var result = _sut.FormatPrice(9.999m);

        Assert.AreEqual("$10.00", result);
    }

    #endregion
}

