+
+    [TestMethod]
+    public void FormatPrice_DefaultCurrency_FormatsWithDollarSign()
+    {
+        var result = _sut.FormatPrice(42.5m);
+
+        Assert.AreEqual("$42.50", result);
+    }
+
+    [TestMethod]
+    public void FormatPrice_CustomCurrency_UsesProvidedSymbol()
+    {
+        var result = _sut.FormatPrice(42.5m, "€");
+
+        Assert.StartsWith("€", result);
+        Assert.AreEqual("€42.50", result);
+    }
+
+    [TestMethod]
+    public void FormatPrice_RoundsToTwoDecimalPlaces()
+    {
+        var result = _sut.FormatPrice(9.999m);
+
+        Assert.AreEqual("$10.00", result);
+    }
